class Solution:
    def splitBST(self, root: 'TreeNode', target: int) -> list['TreeNode']:
        small_dummy, large_dummy = TreeNode(0), TreeNode(0)
        small, large = small_dummy, large_dummy
        while root:
            if root.val <= target:
                small.right = root
                small = root
                root = root.right
            else:
                large.left = root
                large = root
                root = root.left
        small.right = None
        large.left = None
        return [small_dummy.right, large_dummy.left]
